PROFILE Immersive

Viewpoint { }

DEF A1 Anchor {
  description "Synthetic anchor one"
  url "anchor-target-one.wrl#Entry"
  parameter "target=_blank"
  children Transform {
    translation -2 0 0
    children Shape {
      geometry Box {
        size 1 1 1
      }
    }
  }
}

DEF A2 Anchor {
  description "Synthetic anchor two"
  url "anchor-target-two.wrl"
  parameter [
    "a=b",
    "c=d"
  ]
  children Transform {
    translation 2 0 0
    children Shape {
      geometry Sphere { }
    }
  }
}

DEF A3 Anchor {
  children Shape {
    geometry Cone { }
  }
}

